#include <zephyr/ztest.h>
#include <zephyr/sys/linear_range.h>
#include <errno.h>

#define TEST_MIN_VAL_1 0
#define TEST_MAX_VAL_1 10
#define TEST_STEP_VAL_1 1

#define TEST_MIN_VAL_2 10
#define TEST_MAX_VAL_2 100
#define TEST_STEP_VAL_2 10

#define TEST_MIN_VAL_3 50
#define TEST_MAX_VAL_3 50
#define TEST_STEP_VAL_3 1

#define TEST_MIN_VAL_4 -5
#define TEST_MAX_VAL_4 5
#define TEST_STEP_VAL_4 2

static void test_linear_range_get_index(void)
{
    struct linear_range lr;
    int32_t idx;
    int ret;

    /* Test case 1: Simple range (0-10, step 1) */
    ret = linear_range_create(&lr, TEST_MIN_VAL_1, TEST_MAX_VAL_1, TEST_STEP_VAL_1);
    zassert_equal(ret, 0, "Failed to create linear range 1");

    for (int i = TEST_MIN_VAL_1; i <= TEST_MAX_VAL_1; i += TEST_STEP_VAL_1) {
        ret = linear_range_get_index(&lr, i, &idx);
        zassert_equal(ret, 0, "linear_range_get_index failed for value %d", i);
        zassert_equal(idx, (i - TEST_MIN_VAL_1) / TEST_STEP_VAL_1, "Incorrect index for value %d", i);
    }

    /* Test out of bounds */
    ret = linear_range_get_index(&lr, TEST_MIN_VAL_1 - 1, &idx);
    zassert_not_equal(ret, 0, "linear_range_get_index should fail for value %d", TEST_MIN_VAL_1 - 1);
    ret = linear_range_get_index(&lr, TEST_MAX_VAL_1 + 1, &idx);
    zassert_not_equal(ret, 0, "linear_range_get_index should fail for value %d", TEST_MAX_VAL_1 + 1);

    /* Test case 2: Range with negative min_val (-5 to 5, step 2) */
    ret = linear_range_create(&lr, TEST_MIN_VAL_4, TEST_MAX_VAL_4, TEST_STEP_VAL_4);
    zassert_equal(ret, 0, "Failed to create linear range 4");

    for (int i = TEST_MIN_VAL_4; i <= TEST_MAX_VAL_4; i += TEST_STEP_VAL_4) {
        ret = linear_range_get_index(&lr, i, &idx);
        zassert_equal(ret, 0, "linear_range_get_index failed for value %d (range 4)", i);
        zassert_equal(idx, (i - TEST_MIN_VAL_4) / TEST_STEP_VAL_4, "Incorrect index for value %d (range 4)", i);
    }
}

static void test_linear_range_get_max_value(void)
{
    struct linear_range lr;
    int32_t val;
    int ret;

    /* Test case 1: Simple range (0-10, step 1) */
    ret = linear_range_create(&lr, TEST_MIN_VAL_1, TEST_MAX_VAL_1, TEST_STEP_VAL_1);
    zassert_equal(ret, 0, "Failed to create linear range 1");
    ret = linear_range_get_max_value(&lr, &val);
    zassert_equal(ret, 0, "linear_range_get_max_value failed");
    zassert_equal(val, TEST_MAX_VAL_1, "Incorrect max value");

    /* Test case 2: Single value range (50-50, step 1) */
    ret = linear_range_create(&lr, TEST_MIN_VAL_3, TEST_MAX_VAL_3, TEST_STEP_VAL_3);
    zassert_equal(ret, 0, "Failed to create linear range 3");
    ret = linear_range_get_max_value(&lr, &val);
    zassert_equal(ret, 0, "linear_range_get_max_value failed");
    zassert_equal(val, TEST_MAX_VAL_3, "Incorrect max value");
}

static void test_linear_range_get_value(void)
{
    struct linear_range lr;
    int32_t val;
    int ret;
    int num_elements;

    /* Test case 1: Simple range (0-10, step 1) */
    ret = linear_range_create(&lr, TEST_MIN_VAL_1, TEST_MAX_VAL_1, TEST_STEP_VAL_1);
    zassert_equal(ret, 0, "Failed to create linear range 1");
    num_elements = (TEST_MAX_VAL_1 - TEST_MIN_VAL_1) / TEST_STEP_VAL_1 + 1;
    for (int i = 0; i < num_elements; i++) {
        ret = linear_range_get_value(&lr, i, &val);
        zassert_equal(ret, 0, "linear_range_get_value failed for index %d (range 1)", i);
        zassert_equal(val, TEST_MIN_VAL_1 + i * TEST_STEP_VAL_1, "Incorrect value for index %d (range 1)", i);
    }
    /* Test out of bounds */
    ret = linear_range_get_value(&lr, num_elements, &val);
    zassert_not_equal(ret, 0, "linear_range_get_value should fail for out-of-bounds index (range 1)");

    /* Test case 2: Different min_val, max_val, step_val (10-100, step 10) */
    ret = linear_range_create(&lr, TEST_MIN_VAL_2, TEST_MAX_VAL_2, TEST_STEP_VAL_2);
    zassert_equal(ret, 0, "Failed to create linear range 2");
    num_elements = (TEST_MAX_VAL_2 - TEST_MIN_VAL_2) / TEST_STEP_VAL_2 + 1;
    for (int i = 0; i < num_elements; i++) {
        ret = linear_range_get_value(&lr, i, &val);
        zassert_equal(ret, 0, "linear_range_get_value failed for index %d (range 2)", i);
        zassert_equal(val, TEST_MIN_VAL_2 + i * TEST_STEP_VAL_2, "Incorrect value for index %d (range 2)", i);
    }
    /* Test out of bounds */
    ret = linear_range_get_value(&lr, num_elements, &val);
    zassert_not_equal(ret, 0, "linear_range_get_value should fail for out-of-bounds index (range 2)");

    /* Test case 3: Single value range (50-50, step 1) */
    ret = linear_range_create(&lr, TEST_MIN_VAL_3, TEST_MAX_VAL_3, TEST_STEP_VAL_3);
    zassert_equal(ret, 0, "Failed to create linear range 3");
    num_elements = (TEST_MAX_VAL_3 - TEST_MIN_VAL_3) / TEST_STEP_VAL_3 + 1;
    for (int i = 0; i < num_elements; i++) { /* Should only run for i=0 */
        ret = linear_range_get_value(&lr, i, &val);
        zassert_equal(ret, 0, "linear_range_get_value failed for index %d (range 3)", i);
        zassert_equal(val, TEST_MIN_VAL_3 + i * TEST_STEP_VAL_3, "Incorrect value for index %d (range 3)", i);
    }
    /* Test out of bounds */
    ret = linear_range_get_value(&lr, num_elements, &val);
    zassert_not_equal(ret, 0, "linear_range_get_value should fail for out-of-bounds index (range 3)");

    /* Test case 4: Range with negative min_val (-5 to 5, step 2) */
    ret = linear_range_create(&lr, TEST_MIN_VAL_4, TEST_MAX_VAL_4, TEST_STEP_VAL_4);
    zassert_equal(ret, 0, "Failed to create linear range 4");
    num_elements = (TEST_MAX_VAL_4 - TEST_MIN_VAL_4) / TEST_STEP_VAL_4 + 1;
    for (int i = 0; i < num_elements; i++) {
        ret = linear_range_get_value(&lr, i, &val);
        zassert_equal(ret, 0, "linear_range_get_value failed for index %d (range 4)", i);
        zassert_equal(val, TEST_MIN_VAL_4 + i * TEST_STEP_VAL_4, "Incorrect value for index %d (range 4)", i);
    }
    /* Test out of bounds */
    ret = linear_range_get_value(&lr, num_elements, &val);
    zassert_not_equal(ret, 0, "linear_range_get_value should fail for out-of-bounds index (range 4)");

    /* Test case 5: Invalid range creation - step_val <= 0 */
    ret = linear_range_create(&lr, 0, 10, 0);
    zassert_equal(ret, -EINVAL, "linear_range_create should fail for step_val = 0");
    ret = linear_range_create(&lr, 0, 10, -1);
    zassert_equal(ret, -EINVAL, "linear_range_create should fail for negative step_val");

    /* Test case 6: Invalid range creation - min_val > max_val */
    ret = linear_range_create(&lr, 10, 0, 1);
    zassert_equal(ret, -EINVAL, "linear_range_create should fail for min_val > max_val");

    /* Test case 7: Invalid range creation - (max_val - min_val) not multiple of step_val */
    ret = linear_range_create(&lr, 0, 9, 2);
    zassert_equal(ret, -EINVAL, "linear_range_create should fail for non-multiple step");
}

ztest_test_suite(linear_range,
    ztest_unit_test(test_linear_range_get_index),
    ztest_unit_test(test_linear_range_get_max_value),
    ztest_unit_test(test_linear_range_get_value)
);
